class DeleteTest {
    static void check(String label, boolean got, boolean want) {
        if (got != want) throw new AssertionError(label + ": got " + got + ", want " + want);
        System.out.println("OK " + label);
    }
    public static void main(String[] args) {
        Trie t = new Trie();
        t.insert("and"); t.insert("ant"); t.insert("do"); t.insert("dad");

        // delete a leaf word — "ant" shares "an" with "and"
        t.delete("ant");
        check("ant gone",        t.search("ant"),   false);
        check("and preserved",   t.search("and"),   true);
        check("an not a word",   t.search("an"),    false);
        check("an still prefix", t.isPrefix("an"),  true);  // 'a'->'n'->'d' still exists

        // delete a word whose node is a prefix of another — "do" is a prefix of (nothing here, but "dad" shares 'd')
        t.delete("do");
        check("do gone",         t.search("do"),    false);
        check("dad preserved",   t.search("dad"),   true);

        // delete a word not in the trie — should be a no-op
        t.delete("dog");
        check("and still there", t.search("and"),   true);

        // delete the remaining words; trie should be empty
        t.delete("and"); t.delete("dad");
        check("and gone",        t.search("and"),   false);
        check("dad gone",        t.search("dad"),   false);
        check("no prefix a",     t.isPrefix("a"),   false);
        check("no prefix d",     t.isPrefix("d"),   false);
    }
}
